pub fn ranges(xs: List[Int]) -> Str {
  let ys = xs.unique().sort()
  var parts: List[Str] = []
  var i = 0
  while i < ys.len() {
    let first = ys.get_or(i, 0)
    var last_i = i
    while last_i + 1 < ys.len() and ys.get_or(last_i + 1, 0) == ys.get_or(last_i, 0) + 1 {
      last_i = last_i + 1
    }
    let last = ys.get_or(last_i, 0)
    if last_i - i >= 2 {
      parts = parts.push(first.to_str() + "-" + last.to_str())
    } else if last_i - i == 1 {
      parts = parts.push(first.to_str())
      parts = parts.push(last.to_str())
    } else {
      parts = parts.push(first.to_str())
    }
    i = last_i + 1
  }
  return parts.join(",")
}
